void rehash( int newSize )
{
    vector<HashEntry> oldArray = array;

    // 创建新的双倍大小的空散列表
    array.resize( nextPrime( newSize ) );
    for( auto & entry : array )
        entry.isActive = false;

    // 复制整个表
    currentSize = 0;
    for( auto & entry : oldArray )
        if( entry.isActive )
            insert( std::move( entry.element ) );
}

